export const CHATTER: Readonly<Record<string, Row>> = {
  "I wonder who I was. I hope they wouldn't mind.": ["俺は誰だったんだろう。そいつが気にしないといいが。", "내가 누구였을까. 그 사람이 개의치 않았으면.", "我好奇我曾经是谁。希望他不介意。", "我好奇我曾經是誰。希望他不介意。", "Không biết ta từng là ai. Mong người đó không phiền.", "Aku penasaran dulu aku siapa. Semoga ia tak keberatan.", "สงสัยว่าข้าเคยเป็นใคร หวังว่าเขาคงไม่ว่าอะไร", "Kim olduğumu merak ediyorum. Umarım aldırmaz.", "Me pregunto quién fui. Espero que no le importe.", "Fico pensando em quem eu fui. Espero que não se importe.", "Интересно, кем я был. Надеюсь, он не против.", "Цікаво, ким я був. Сподіваюся, він не проти."],
  "Everyone's a skeleton underneath. I'm just honest about it.": ["誰だって中身は骸骨だ。俺は正直なだけ。", "다들 속은 해골이야. 난 솔직할 뿐이고.", "人人底下都是骷髅。我只是比较诚实。", "人人底下都是骷髏。我只是比較誠實。", "Ai bên trong cũng là bộ xương. Ta chỉ thành thật thôi.", "Semua orang di dalamnya kerangka. Aku cuma jujur.", "ทุกคนข้างในก็คือโครงกระดูก ข้าแค่ซื่อตรง", "Herkes içten içe iskelet. Ben sadece dürüstüm.", "Todo el mundo es un esqueleto por dentro. Yo solo soy sincero.", "Todo mundo é esqueleto por dentro. Eu só sou honesto.", "Под кожей все скелеты. Я просто честен.", "Під шкірою всі скелети. Я просто чесний."],
  "My knees click. I don't have knees.": ["膝が鳴る。膝なんてないのに。", "무릎에서 딱딱 소리가 나. 무릎도 없는데.", "我的膝盖咔咔响。我没有膝盖。", "我的膝蓋咔咔響。我沒有膝蓋。", "Đầu gối ta kêu lách cách. Ta làm gì có đầu gối.", "Lututku berbunyi. Aku tak punya lutut.", "เข่าข้าลั่น ข้าไม่มีเข่าด้วยซ้ำ", "Dizlerim tıkırdıyor. Dizim yok ki.", "Me crujen las rodillas. No tengo rodillas.", "Meus joelhos estalam. Eu não tenho joelhos.", "Колени щёлкают. У меня нет коленей.", "Коліна клацають. У мене нема колін."],
  "You go on ahead. I'll haunt the back.": ["先に行け。俺は後ろで化けて出る。", "먼저 가. 난 뒤에서 어슬렁거릴게.", "你先走。我在后面飘着。", "你先走。我在後面飄著。", "Ngươi đi trước. Ta lảng vảng phía sau.", "Kamu duluan. Aku gentayangan di belakang.", "เจ้าไปก่อน ข้าจะหลอกหลอนอยู่ข้างหลัง", "Sen öne geç. Ben arkada dolanırım.", "Tú ve delante. Yo rondaré por detrás.", "Vai na frente. Eu assombro a retaguarda.", "Иди вперёд. Я буду бродить сзади.", "Іди вперед. Я блукатиму позаду."],
  "People stare. Let them. Good bones.": ["みんなじろじろ見る。見させとけ。いい骨格だからな。", "다들 쳐다봐. 보라고 해. 뼈대가 좋으니까.", "大家盯着看。随他们。骨相好。", "大家盯著看。隨他們。骨相好。", "Người ta nhìn chằm chằm. Mặc họ. Xương đẹp mà.", "Orang menatap. Biarkan. Tulangnya bagus.", "คนจ้องมอง ช่างเขา กระดูกดี", "İnsanlar bakıyor. Baksınlar. İyi kemikler.", "La gente mira. Que miren. Buena osamenta.", "As pessoas encaram. Deixa. Ossos bonitos.", "Пялятся. Пусть. Хорошие кости.", "Витріщаються. Хай. Гарні кістки."],
  "Do you ever think about the bones you're carrying around? I do.": ["自分が持ち歩いてる骨のこと、考えたことある？俺はある。", "네가 들고 다니는 뼈에 대해 생각해 본 적 있어？난 있어.", "你想过自己身上带着的骨头吗？我想过。", "你想過自己身上帶著的骨頭嗎？我想過。", "Ngươi có bao giờ nghĩ về bộ xương mình mang theo không? Ta thì có.", "Pernah memikirkan tulang yang kau bawa ke mana-mana? Aku pernah.", "เคยคิดถึงกระดูกที่เจ้าแบกไปไหนมาไหนไหม ข้าคิด", "Taşıdığın kemikleri hiç düşünür müsün? Ben düşünürüm.", "¿Alguna vez piensas en los huesos que llevas encima? Yo sí.", "Você já pensou nos ossos que carrega por aí? Eu já.", "Ты когда-нибудь думаешь о костях, что носишь в себе? Я — да.", "Ти колись думаєш про кістки, що носиш у собі? Я — так."],
  "I can whistle through my ribs. Don't ask me to.": ["肋骨で口笛が吹ける。頼むなよ。", "갈비뼈로 휘파람 불 수 있어. 시키지는 마.", "我能用肋骨吹口哨。别让我吹。", "我能用肋骨吹口哨。別讓我吹。", "Ta huýt sáo qua xương sườn được. Đừng bảo ta làm.", "Aku bisa bersiul lewat rusukku. Jangan minta.", "ข้าผิวปากผ่านซี่โครงได้ อย่าขอให้ทำ", "Kaburgalarımdan ıslık çalabilirim. Benden isteme.", "Puedo silbar con las costillas. No me lo pidas.", "Consigo assobiar pelas costelas. Não me peça.", "Я умею свистеть рёбрами. Не проси.", "Я вмію свистіти ребрами. Не проси."],
  "Who's behind your face? Who's behind that one?": ["お前の顔の裏には誰がいる？その裏には？", "네 얼굴 뒤엔 누가 있지？그 뒤엔？", "你的脸后面是谁？那张后面又是谁？", "你的臉後面是誰？那張後面又是誰？", "Ai đứng sau khuôn mặt ngươi? Ai sau khuôn mặt đó?", "Siapa di balik wajahmu? Siapa di balik yang itu?", "ใครอยู่หลังใบหน้าเจ้า แล้วใครอยู่หลังอันนั้น", "Yüzünün ardında kim var? Onun ardında kim?", "¿Quién hay tras tu cara? ¿Y tras esa?", "Quem está atrás do seu rosto? E atrás desse?", "Кто за твоим лицом? А за тем?", "Хто за твоїм обличчям? А за тим?"],
  "They think they know me. They know the mask.": ["俺を知ってるつもりだ。知ってるのは仮面だ。", "날 안다고 생각하지. 아는 건 가면이야.", "他们以为认识我。他们认识的是面具。", "他們以為認識我。他們認識的是面具。", "Họ tưởng họ biết ta. Họ biết mặt nạ thôi.", "Mereka kira kenal aku. Mereka kenal topengnya.", "พวกเขาคิดว่ารู้จักข้า เขารู้จักหน้ากาก", "Beni tanıdıklarını sanıyorlar. Maskeyi tanıyorlar.", "Creen que me conocen. Conocen la máscara.", "Acham que me conhecem. Conhecem a máscara.", "Думают, что знают меня. Знают маску.", "Думають, що знають мене. Знають маску."],
  "I wore a different face yesterday. You didn't notice.": ["昨日は別の顔をしていた。気づかなかったな。", "어제는 다른 얼굴이었어. 몰랐지.", "我昨天戴的是另一张脸。你没注意到。", "我昨天戴的是另一張臉。你沒注意到。", "Hôm qua ta mang khuôn mặt khác. Ngươi không để ý.", "Kemarin aku memakai wajah lain. Kau tak sadar.", "เมื่อวานข้าใส่หน้าอื่น เจ้าไม่สังเกต", "Dün başka bir yüz takmıştım. Fark etmedin.", "Ayer llevaba otra cara. No te diste cuenta.", "Ontem eu usava outro rosto. Você não notou.", "Вчера у меня было другое лицо. Ты не заметил.", "Учора в мене було інше обличчя. Ти не помітив."],
  "Say less.": ["口数を減らせ。", "말 줄여.", "少说点。", "少說點。", "Nói ít thôi.", "Bicara lebih sedikit.", "พูดให้น้อยลง", "Az konuş.", "Habla menos.", "Fale menos.", "Говори меньше.", "Говори менше."],
  "Everyone wears one. Mine's just honest about it.": ["誰だって仮面をつけてる。俺のは正直なだけ。", "다들 하나씩 쓰고 있어. 내 건 솔직할 뿐.", "人人都戴着一张。我的只是比较诚实。", "人人都戴著一張。我的只是比較誠實。", "Ai cũng đeo một chiếc. Chiếc của ta thành thật thôi.", "Semua memakainya. Punyaku cuma jujur.", "ทุกคนใส่ ของข้าแค่ซื่อตรง", "Herkes bir tane takar. Benimki dürüst sadece.", "Todos llevan una. La mía es sincera, nada más.", "Todo mundo usa uma. A minha só é honesta.", "Все носят маску. Моя просто честная.", "Усі носять маску. Моя просто чесна."],
  "…I like this place.": ["…ここは気に入った。", "…여기 좋다.", "……我喜欢这里。", "……我喜歡這裡。", "…ta thích chỗ này.", "…aku suka tempat ini.", "…ข้าชอบที่นี่", "…burayı sevdim.", "…me gusta este sitio.", "…gosto daqui.", "…мне здесь нравится.", "…мені тут подобається."],
  "Did you remember to eat?": ["ちゃんと食べた？", "밥 챙겨 먹었니？", "你记得吃饭了吗？", "你記得吃飯了嗎？", "Con nhớ ăn chưa?", "Sudah ingat makan?", "กินข้าวหรือยัง", "Yemek yemeyi unutmadın mı?", "¿Te has acordado de comer?", "Lembrou de comer?", "Ты не забыл поесть?", "Ти не забув поїсти?"],
  "We should visit Grandma. We don't have a Grandma. We should find one.": ["おばあちゃんに会いに行かなきゃ。おばあちゃんいないけど。探さなきゃ。", "할머니 뵈러 가야지. 우리 할머니 없잖아. 하나 찾아야겠다.", "我们该去看奶奶。我们没有奶奶。该找一个。", "我們該去看奶奶。我們沒有奶奶。該找一個。", "Mình nên đi thăm bà. Mình không có bà. Nên tìm một bà.", "Kita harus menjenguk Nenek. Kita tak punya Nenek. Harus cari satu.", "เราควรไปเยี่ยมคุณยาย เราไม่มีคุณยาย ต้องหาสักคน", "Büyükanneyi ziyaret etmeliyiz. Büyükannemiz yok. Bir tane bulmalıyız.", "Deberíamos visitar a la abuela. No tenemos abuela. Habrá que buscar una.", "A gente devia visitar a vovó. Não temos vovó. Devíamos arranjar uma.", "Надо навестить бабушку. У нас нет бабушки. Надо найти.", "Треба провідати бабусю. У нас нема бабусі. Треба знайти."],
  "Is it bedtime? It's nearly bedtime.": ["もう寝る時間？もうすぐ寝る時間よ。", "잘 시간이야？거의 잘 시간이네.", "该睡觉了吗？快到睡觉时间了。", "該睡覺了嗎？快到睡覺時間了。", "Đến giờ ngủ chưa? Sắp đến giờ ngủ rồi.", "Sudah waktunya tidur? Hampir waktunya tidur.", "ถึงเวลานอนหรือยัง ใกล้เวลานอนแล้ว", "Yatma vakti mi? Neredeyse yatma vakti.", "¿Es hora de dormir? Casi es hora de dormir.", "Já é hora de dormir? Está quase.", "Пора спать? Почти пора спать.", "Час спати? Майже час спати."],
  "I packed a spare scarf. You'll thank me.": ["予備のマフラーを入れておいたわ。感謝するわよ。", "여분 목도리 챙겼어. 고마워하게 될걸.", "我多装了条围巾。你会谢我的。", "我多裝了條圍巾。你會謝我的。", "Ta đã gói thêm khăn quàng. Rồi con sẽ cảm ơn ta.", "Aku membawa syal cadangan. Kau akan berterima kasih.", "ฉันใส่ผ้าพันคอสำรองไว้ เดี๋ยวก็ขอบคุณ", "Yedek atkı koydum. Bana teşekkür edeceksin.", "He metido una bufanda de repuesto. Ya me lo agradecerás.", "Coloquei um cachecol extra. Você vai me agradecer.", "Я взяла запасной шарф. Ещё спасибо скажешь.", "Я взяла запасний шарф. Ще подякуєш."],
  "Nice people here. Mostly.": ["ここの人たちは優しいわ。だいたいは。", "여기 사람들 좋네. 대체로.", "这里的人挺好。大部分。", "這裡的人挺好。大部分。", "Người ở đây tốt. Phần lớn.", "Orang-orang di sini baik. Kebanyakan.", "คนที่นี่ใจดี ส่วนใหญ่", "Buradaki insanlar iyi. Çoğu.", "La gente de aquí es maja. Casi toda.", "Gente boa aqui. Quase toda.", "Хорошие тут люди. В основном.", "Гарні тут люди. Здебільшого."],
  "Write home. I'll tell you what to say.": ["家に手紙を書いて。何を書くか教えてあげる。", "집에 편지 써. 뭐라고 쓸지 알려 줄게.", "给家里写信。我告诉你写什么。", "給家裡寫信。我告訴你寫什麼。", "Viết thư về nhà đi. Ta sẽ bảo con viết gì.", "Tulis surat ke rumah. Kuberi tahu isinya.", "เขียนจดหมายกลับบ้าน เดี๋ยวบอกว่าเขียนอะไร", "Eve yaz. Ne yazacağını ben söylerim.", "Escribe a casa. Yo te digo qué poner.", "Escreve pra casa. Eu digo o que falar.", "Напиши домой. Я подскажу, что писать.", "Напиши додому. Я підкажу, що писати."],
  "What's for supper?": ["晩ご飯は何？", "저녁은 뭐야？", "晚饭吃什么？", "晚飯吃什麼？", "Tối nay ăn gì?", "Makan malam apa?", "มื้อเย็นกินอะไร", "Akşam yemeğinde ne var?", "¿Qué hay de cena?", "O que tem pro jantar?", "Что на ужин?", "Що на вечерю?"],
  "I counted the stars. I lost count. Starting again.": ["星を数えた。わからなくなった。やり直す。", "별을 셌어. 놓쳤어. 다시 시작.", "我数了星星。数乱了。重来。", "我數了星星。數亂了。重來。", "Ta đếm sao. Đếm lạc. Đếm lại.", "Aku menghitung bintang. Lupa hitungan. Mulai lagi.", "นับดาว นับพลาด เริ่มใหม่", "Yıldızları saydım. Şaşırdım. Yeniden başlıyorum.", "He contado las estrellas. Me he perdido. Vuelvo a empezar.", "Contei as estrelas. Perdi a conta. Recomeçando.", "Я считал звёзды. Сбился. Начинаю заново.", "Я рахував зорі. Збився. Починаю знову."],
  "Everything's made of smaller things. Even that.": ["何でも小さなものでできている。あれさえも。", "모든 건 더 작은 것들로 이뤄져. 저것도.", "万物都由更小的东西组成。那个也是。", "萬物都由更小的東西組成。那個也是。", "Mọi thứ đều làm từ những thứ nhỏ hơn. Cả cái đó.", "Semuanya terbuat dari hal yang lebih kecil. Bahkan itu.", "ทุกอย่างประกอบจากสิ่งที่เล็กกว่า แม้แต่นั่น", "Her şey daha küçük şeylerden oluşur. O bile.", "Todo está hecho de cosas más pequeñas. Incluso eso.", "Tudo é feito de coisas menores. Até aquilo.", "Всё состоит из чего-то меньшего. Даже это.", "Усе складається з чогось меншого. Навіть це."],
  "Hypothesis: it'll rain. Evidence: it's raining.": ["仮説：雨が降る。証拠：降っている。", "가설： 비가 올 거다. 증거： 비가 온다.", "假设：会下雨。证据：正在下雨。", "假設：會下雨。證據：正在下雨。", "Giả thuyết: trời sẽ mưa. Bằng chứng: trời đang mưa.", "Hipotesis: akan hujan. Bukti: sedang hujan.", "สมมติฐาน: ฝนจะตก หลักฐาน: ฝนกำลังตก", "Hipotez: yağmur yağacak. Kanıt: yağıyor.", "Hipótesis: lloverá. Prueba: está lloviendo.", "Hipótese: vai chover. Evidência: está chovendo.", "Гипотеза: будет дождь. Доказательство: идёт дождь.", "Гіпотеза: буде дощ. Доказ: іде дощ."],
  "The birds here sing a tone lower. Noted.": ["ここの鳥は一音低く鳴く。記録した。", "여기 새들은 한 음 낮게 울어. 기록함.", "这里的鸟叫低一个音。已记录。", "這裡的鳥叫低一個音。已記錄。", "Chim ở đây hót thấp hơn một cung. Đã ghi.", "Burung di sini berkicau satu nada lebih rendah. Dicatat.", "นกที่นี่ร้องต่ำลงหนึ่งเสียง จดไว้แล้ว", "Buradaki kuşlar bir ton pes ötüyor. Not edildi.", "Los pájaros de aquí cantan un tono más bajo. Anotado.", "Os pássaros daqui cantam um tom abaixo. Anotado.", "Птицы здесь поют на тон ниже. Отмечено.", "Птахи тут співають на тон нижче. Занотовано."],
  "What would happen if we planted a coin?": ["お金を植えたらどうなるだろう？", "동전을 심으면 어떻게 될까？", "要是我们种下一枚硬币会怎样？", "要是我們種下一枚硬幣會怎樣？", "Nếu trồng một đồng xu thì sao nhỉ?", "Apa yang terjadi kalau kita menanam koin?", "ถ้าเราปลูกเหรียญจะเกิดอะไรขึ้น", "Bir para eksek ne olurdu?", "¿Qué pasaría si plantáramos una moneda?", "O que aconteceria se plantássemos uma moeda?", "Что будет, если посадить монету?", "Що буде, якщо посадити монету?"],
  "The soil here is wrong. Interestingly wrong.": ["ここの土はおかしい。興味深くおかしい。", "여기 흙이 이상해. 흥미롭게 이상해.", "这里的土不对劲。有意思地不对劲。", "這裡的土不對勁。有意思地不對勁。", "Đất ở đây sai sai. Sai một cách thú vị.", "Tanah di sini aneh. Aneh yang menarik.", "ดินที่นี่ผิดปกติ ผิดแบบน่าสนใจ", "Buranın toprağı tuhaf. İlginç biçimde tuhaf.", "El suelo aquí está mal. Interesantemente mal.", "O solo aqui está errado. Interessantemente errado.", "Почва здесь неправильная. Любопытно неправильная.", "Ґрунт тут неправильний. Цікаво неправильний."],
  "I've been dividing. Don't look.": ["分裂中だ。見ないで。", "분열 중이야. 보지 마.", "我在分裂。别看。", "我在分裂。別看。", "Ta đang phân bào. Đừng nhìn.", "Aku sedang membelah. Jangan lihat.", "ข้ากำลังแบ่งตัว อย่ามอง", "Bölünüyorum. Bakma.", "Me estoy dividiendo. No mires.", "Estou me dividindo. Não olha.", "Я делюсь. Не смотри.", "Я ділюся. Не дивись."],
  "Everything leans. Trees, houses, me. Especially me.": ["何でも傾いてる。木も、家も、俺も。特に俺が。", "다 기울어. 나무、 집、 나. 특히 나.", "什么都歪。树、房子、我。尤其是我。", "什麼都歪。樹、房子、我。尤其是我。", "Mọi thứ đều nghiêng. Cây, nhà, ta. Nhất là ta.", "Semua miring. Pohon, rumah, aku. Terutama aku.", "ทุกอย่างเอียง ต้นไม้ บ้าน ข้า โดยเฉพาะข้า", "Her şey eğik. Ağaçlar, evler, ben. Özellikle ben.", "Todo se inclina. Árboles, casas, yo. Sobre todo yo.", "Tudo pende. Árvores, casas, eu. Principalmente eu.", "Всё кренится. Деревья, дома, я. Особенно я.", "Усе хилиться. Дерева, будинки, я. Особливо я."],
  "Is the world crooked, or is it just me? Both. Both is fine.": ["世界が曲がってるのか、俺だけか？両方だ。両方でいい。", "세상이 삐뚤어진 걸까、 나만 그런 걸까？둘 다. 둘 다 괜찮아.", "是世界歪了，还是只有我？都是。都是也行。", "是世界歪了，還是只有我？都是。都是也行。", "Thế giới lệch hay chỉ mình ta? Cả hai. Cả hai cũng được.", "Dunia yang miring, atau aku saja? Dua-duanya. Tak apa.", "โลกเบี้ยว หรือข้าเบี้ยวคนเดียว ทั้งคู่ ทั้งคู่ก็ได้", "Dünya mı yamuk, ben mi? İkisi de. İkisi de olur.", "¿El mundo está torcido o soy yo? Los dos. Está bien así.", "O mundo é torto ou sou eu? Os dois. Tudo bem.", "Мир кривой или только я? Оба. И ладно.", "Світ кривий чи лише я? Обоє. І гаразд."],
  "I fell over. I meant to.": ["転んだ。わざとだ。", "넘어졌어. 일부러야.", "我摔倒了。故意的。", "我摔倒了。故意的。", "Ta ngã. Cố ý đấy.", "Aku jatuh. Sengaja.", "ข้าล้ม ตั้งใจ", "Düştüm. Bilerek.", "Me he caído. Queriendo.", "Caí. Foi de propósito.", "Я упал. Так и задумано.", "Я впав. Так і задумано."],
  "Which way's up? Trick question. Diagonal.": ["どっちが上？ひっかけ問題。斜めだ。", "어느 쪽이 위게？함정 문제. 대각선.", "哪边是上？脑筋急转弯。斜的。", "哪邊是上？腦筋急轉彎。斜的。", "Đâu là trên? Câu đố mẹo. Đường chéo.", "Mana atas? Pertanyaan jebakan. Diagonal.", "ทางไหนขึ้น คำถามหลอก ทแยง", "Yukarısı ne tarafı? Şaşırtmaca. Çapraz.", "¿Dónde es arriba? Pregunta trampa. En diagonal.", "Qual lado é pra cima? Pegadinha. Diagonal.", "Где верх? Вопрос с подвохом. По диагонали.", "Де верх? Питання з підступом. По діагоналі."],
  "Nothing lines up. Beautiful.": ["何も揃ってない。美しい。", "줄 맞는 게 없어. 아름다워.", "什么都不对齐。真美。", "什麼都不對齊。真美。", "Chẳng gì thẳng hàng. Đẹp.", "Tak ada yang lurus. Indah.", "ไม่มีอะไรตรงกัน สวยงาม", "Hiçbir şey hizada değil. Güzel.", "Nada está alineado. Precioso.", "Nada se alinha. Lindo.", "Ничего не ровно. Красота.", "Нічого не рівно. Краса."],
  "What's over there? And there? And THERE?": ["あっちは何？あっちは？あっちは？", "저긴 뭐야？저긴？저기는？", "那边有什么？那边呢？那边呢？", "那邊有什麼？那邊呢？那邊呢？", "Đằng kia có gì? Kia nữa? KIA NỮA?", "Ada apa di sana? Dan sana? Dan SANA?", "ตรงนั้นมีอะไร ตรงนั้นล่ะ ตรงนั้นล่ะ", "Orada ne var? Ya orada? Ya ORADA?", "¿Qué hay allí? ¿Y allí? ¿Y ALLÍ?", "O que tem ali? E ali? E ALI?", "Что там? А там? А ТАМ?", "Що там? А там? А ТАМ?"],
  "Everything's better from higher up.": ["高いところから見ると何でもよく見える。", "높은 데서 보면 다 더 좋아.", "从高处看什么都更好。", "從高處看什麼都更好。", "Từ trên cao cái gì cũng đẹp hơn.", "Semuanya lebih baik dari atas.", "ทุกอย่างดีกว่าเมื่อมองจากที่สูง", "Her şey yukarıdan daha güzel.", "Todo es mejor desde más arriba.", "Tudo é melhor lá do alto.", "Сверху всё лучше.", "Згори все краще."],
  "I can see the sea from here. I can't. I want to.": ["ここから海が見える。見えない。見たい。", "여기서 바다가 보여. 안 보여. 보고 싶어.", "我从这里能看到海。看不到。我想看。", "我從這裡能看到海。看不到。我想看。", "Từ đây ta thấy biển. Không thấy. Ta muốn thấy.", "Aku bisa lihat laut dari sini. Tidak bisa. Aku ingin.", "เห็นทะเลจากตรงนี้ ไม่เห็นหรอก อยากเห็น", "Buradan denizi görebiliyorum. Göremiyorum. Görmek istiyorum.", "Desde aquí veo el mar. No lo veo. Quiero verlo.", "Daqui dá pra ver o mar. Não dá. Quero ver.", "Отсюда видно море. Не видно. Хочу увидеть.", "Звідси видно море. Не видно. Хочу побачити."],
  "Race you to that tree! You lost. Again!": ["あの木まで競争！負けたね。また！", "저 나무까지 경주！졌다. 또！", "比赛跑到那棵树！你输了。又输了！", "比賽跑到那棵樹！你輸了。又輸了！", "Đua tới cái cây kia! Ngươi thua. Lại thua!", "Balapan ke pohon itu! Kamu kalah. Lagi!", "แข่งไปต้นไม้นั้น! เจ้าแพ้ อีกแล้ว!", "Şu ağaca kadar yarış! Kaybettin. Yine!", "¡Una carrera hasta ese árbol! Has perdido. ¡Otra vez!", "Corrida até aquela árvore! Você perdeu. De novo!", "Наперегонки до того дерева! Ты проиграл. Опять!", "Наввипередки до того дерева! Ти програв. Знову!"],
  "Let's go somewhere we've never been. Now!": ["行ったことない場所へ行こう。今すぐ！", "한 번도 안 가 본 데 가자. 지금！", "去一个我们从没去过的地方。现在！", "去一個我們從沒去過的地方。現在！", "Đi đâu đó mình chưa từng tới. Ngay!", "Ayo ke tempat yang belum pernah kita datangi. Sekarang!", "ไปที่ที่เราไม่เคยไปกัน เดี๋ยวนี้!", "Hiç gitmediğimiz bir yere gidelim. Hemen!", "¡Vamos a algún sitio donde no hayamos estado! ¡Ya!", "Vamos pra um lugar onde nunca fomos. Agora!", "Пойдём туда, где мы не были. Сейчас!", "Ходімо туди, де ми не були. Зараз!"],
  "I'm bored. Say something. Anything!": ["退屈。何か言って。何でもいい！", "심심해. 뭐라도 말해. 아무거나！", "好无聊。说点什么。什么都行！", "好無聊。說點什麼。什麼都行！", "Chán quá. Nói gì đi. Gì cũng được!", "Bosan. Bilang sesuatu. Apa saja!", "เบื่อ พูดอะไรหน่อย อะไรก็ได้!", "Sıkıldım. Bir şey söyle. Herhangi bir şey!", "Me aburro. Di algo. ¡Lo que sea!", "Tô entediado. Fala alguma coisa. Qualquer coisa!", "Скучно. Скажи что-нибудь. Что угодно!", "Нудно. Скажи щось. Будь-що!"],
  "Can we fly today? Jump. Try!": ["今日は飛べる？跳んで。やってみて！", "오늘은 날 수 있을까？뛰어 봐. 해 봐！", "今天能飞吗？跳。试试！", "今天能飛嗎？跳。試試！", "Hôm nay bay được không? Nhảy đi. Thử xem!", "Bisa terbang hari ini? Lompat. Coba!", "วันนี้บินได้ไหม กระโดดสิ ลองดู!", "Bugün uçabilir miyiz? Zıpla. Dene!", "¿Podemos volar hoy? Salta. ¡Prueba!", "Dá pra voar hoje? Pula. Tenta!", "Сегодня полетаем? Прыгай. Попробуй!", "Сьогодні політаємо? Стрибай. Спробуй!"],
  "Big sky.": ["でかい空。", "큰 하늘.", "天很大。", "天很大。", "Trời rộng.", "Langit luas.", "ฟ้ากว้าง", "Koca gökyüzü.", "Cielo grande.", "Céu grande.", "Большое небо.", "Велике небо."],
  "Could lift that house. Won't.": ["あの家を持ち上げられる。やらない。", "저 집 들 수 있어. 안 들 거야.", "能举起那房子。不举。", "能舉起那房子。不舉。", "Nâng được cái nhà đó. Không nâng.", "Bisa angkat rumah itu. Tidak mau.", "ยกบ้านนั้นได้ ไม่ยก", "O evi kaldırabilirim. Kaldırmam.", "Podría levantar esa casa. No lo haré.", "Dava pra levantar aquela casa. Não vou.", "Могу поднять тот дом. Не буду.", "Можу підняти той будинок. Не буду."],
  "Good rock there.": ["あそこにいい岩。", "저기 좋은 바위.", "那边有块好石头。", "那邊有塊好石頭。", "Đá tốt đằng kia.", "Batu bagus di sana.", "ตรงนั้นหินดี", "Orada iyi kaya.", "Buena roca allí.", "Pedra boa ali.", "Там хороший камень.", "Там добрий камінь."],
  "Something small ran past. Fine.": ["小さいのが走っていった。かまわん。", "작은 게 지나갔어. 괜찮아.", "有个小东西跑过去了。没事。", "有個小東西跑過去了。沒事。", "Có con gì nhỏ chạy qua. Được.", "Sesuatu yang kecil lewat. Tak apa.", "อะไรตัวเล็กวิ่งผ่าน ไม่เป็นไร", "Küçük bir şey koşup geçti. Olsun.", "Algo pequeño pasó corriendo. Da igual.", "Algo pequeno passou correndo. Tudo bem.", "Что-то мелкое пробежало. Ладно.", "Щось дрібне пробігло. Гаразд."],
  "Walk. Walking is good.": ["歩く。歩くのはいい。", "걸어. 걷는 건 좋아.", "走。走路好。", "走。走路好。", "Đi. Đi bộ tốt.", "Jalan. Jalan itu bagus.", "เดิน เดินดี", "Yürü. Yürümek iyi.", "Caminar. Caminar es bueno.", "Andar. Andar é bom.", "Идём. Ходить хорошо.", "Ідемо. Ходити добре."],
  "Look at the light! Just look!": ["光を見て！とにかく見て！", "빛 좀 봐！그냥 봐！", "看那光！快看！", "看那光！快看！", "Nhìn ánh sáng kìa! Nhìn đi!", "Lihat cahayanya! Lihat saja!", "ดูแสงสิ! ดูเถอะ!", "Işığa bak! Sadece bak!", "¡Mira la luz! ¡Mírala!", "Olha a luz! Só olha!", "Посмотри на свет! Просто посмотри!", "Подивись на світло! Просто подивись!"],
  "Everything's pretty if you squint. Squint!": ["目を細めれば何でもきれい。細めて！", "눈을 가늘게 뜨면 다 예뻐. 떠 봐！", "眯起眼睛什么都好看。眯眼！", "瞇起眼睛什麼都好看。瞇眼！", "Nheo mắt lại thì cái gì cũng đẹp. Nheo đi!", "Semuanya cantik kalau kau memicingkan mata. Coba!", "หรี่ตาแล้วทุกอย่างก็สวย หรี่สิ!", "Gözlerini kısarsan her şey güzel. Kıs!", "Todo es bonito si entornas los ojos. ¡Entórnalos!", "Tudo fica bonito se você apertar os olhos. Aperta!", "Всё красиво, если прищуриться. Прищурься!", "Усе гарне, якщо примружитися. Примружся!"],
  "I'd like a hat with a jewel on it. Two jewels.": ["宝石つきの帽子が欲しいな。宝石ふたつ。", "보석 달린 모자가 갖고 싶어. 보석 두 개.", "我想要一顶镶宝石的帽子。两颗宝石。", "我想要一頂鑲寶石的帽子。兩顆寶石。", "Ta muốn một chiếc mũ đính ngọc. Hai viên ngọc.", "Aku ingin topi berpermata. Dua permata.", "อยากได้หมวกประดับอัญมณี สองเม็ด", "Mücevherli bir şapka isterdim. İki mücevherli.", "Me gustaría un sombrero con una joya. Dos joyas.", "Queria um chapéu com uma joia. Duas joias.", "Хочу шляпу с камнем. С двумя камнями.", "Хочу капелюх із камінцем. З двома камінцями."],
  "Oh! A butterfly! Oh! Another one!": ["あっ！蝶々！あっ！もう一匹！", "앗！나비다！앗！또 있어！", "哦！一只蝴蝶！哦！又一只！", "哦！一隻蝴蝶！哦！又一隻！", "Ồ! Một con bướm! Ồ! Thêm con nữa!", "Oh! Kupu-kupu! Oh! Satu lagi!", "โอ้! ผีเสื้อ! โอ้! อีกตัว!", "Ah! Bir kelebek! Ah! Bir tane daha!", "¡Oh! ¡Una mariposa! ¡Oh! ¡Otra!", "Ah! Uma borboleta! Ah! Outra!", "Ой! Бабочка! Ой! Ещё одна!", "Ой! Метелик! Ой! Ще один!"],
  "Shine on, everything.": ["みんな、輝き続けて。", "모두들、 계속 빛나.", "一切，继续闪耀吧。", "一切，繼續閃耀吧。", "Mọi thứ ơi, cứ tỏa sáng nhé.", "Bersinarlah terus, semuanya.", "ทุกสิ่ง เปล่งประกายต่อไปนะ", "Parlamaya devam, her şey.", "Seguid brillando, todos.", "Continuem brilhando, tudo.", "Сияй, всё на свете.", "Сяй, усе на світі."],
  "Twinkle. That's all I'm saying. Twinkle.": ["キラッ。言いたいのはそれだけ。キラッ。", "반짝. 하고 싶은 말은 그거야. 반짝.", "闪。我就说这个。闪。", "閃。我就說這個。閃。", "Lấp lánh. Ta chỉ nói thế. Lấp lánh.", "Berkelip. Itu saja kataku. Berkelip.", "วิบวับ แค่นั้นแหละ วิบวับ", "Parılda. Tek söylediğim bu. Parılda.", "Destella. Es todo lo que digo. Destella.", "Cintila. É só o que digo. Cintila.", "Мерцай. Вот и всё. Мерцай.", "Мерехти. Ото й усе. Мерехти."],
  "The hum changed.": ["唸りが変わった。", "웅웅거림이 바뀌었어.", "嗡鸣变了。", "嗡鳴變了。", "Tiếng ngân đã đổi.", "Dengungnya berubah.", "เสียงฮัมเปลี่ยนไป", "Uğultu değişti.", "El zumbido ha cambiado.", "O zumbido mudou.", "Гул изменился.", "Гул змінився."],
  "Something under us just turned over.": ["今、下で何かが寝返りを打った。", "방금 우리 아래 뭔가가 뒤척였어.", "我们下面刚才有东西翻了个身。", "我們下面剛才有東西翻了個身。", "Có gì dưới chân ta vừa trở mình.", "Sesuatu di bawah kita baru saja berbalik.", "มีบางอย่างข้างใต้เราเพิ่งพลิกตัว", "Altımızda bir şey az önce döndü.", "Algo debajo de nosotros acaba de darse la vuelta.", "Algo embaixo de nós acabou de se revirar.", "Что-то под нами только что перевернулось.", "Щось під нами щойно перевернулося."],
  "I was elsewhere for a moment. I'm back.": ["一瞬、別の場所にいた。戻った。", "잠깐 다른 데 있었어. 돌아왔어.", "我刚才去别处待了一下。回来了。", "我剛才去別處待了一下。回來了。", "Ta vừa ở nơi khác một lúc. Ta về rồi.", "Aku sempat di tempat lain. Aku kembali.", "เมื่อครู่ข้าอยู่ที่อื่น กลับมาแล้ว", "Bir an başka yerdeydim. Döndüm.", "Estuve en otra parte un momento. He vuelto.", "Estive em outro lugar por um instante. Voltei.", "Я на миг был в другом месте. Вернулся.", "Я на мить був деінде. Повернувся."],
  "I know what's under this field. I won't say.": ["この野原の下に何があるか知っている。言わない。", "이 들판 아래 뭐가 있는지 알아. 말 안 할 거야.", "我知道这片田下面有什么。我不说。", "我知道這片田下面有什麼。我不說。", "Ta biết dưới cánh đồng này có gì. Ta không nói.", "Aku tahu apa di bawah ladang ini. Tak akan kukatakan.", "ข้ารู้ว่าใต้ทุ่งนี้มีอะไร ข้าไม่บอก", "Bu tarlanın altında ne olduğunu biliyorum. Söylemem.", "Sé lo que hay bajo este campo. No lo diré.", "Sei o que tem debaixo deste campo. Não vou dizer.", "Я знаю, что под этим полем. Не скажу.", "Я знаю, що під цим полем. Не скажу."],
  "Cold. Always a little cold. It's fine.": ["冷たい。いつも少し冷たい。平気だ。", "추워. 늘 조금 추워. 괜찮아.", "冷。总是有点冷。没事。", "冷。總是有點冷。沒事。", "Lạnh. Luôn hơi lạnh. Không sao.", "Dingin. Selalu agak dingin. Tak apa.", "หนาว หนาวนิดๆ เสมอ ไม่เป็นไร", "Soğuk. Hep biraz soğuk. Sorun değil.", "Frío. Siempre un poco de frío. No pasa nada.", "Frio. Sempre um pouco de frio. Tudo bem.", "Холодно. Всегда немного холодно. Ничего.", "Холодно. Завжди трохи холодно. Нічого."],
  "They're nearly ready to come back. Not yet.": ["奴らはもうすぐ戻ってくる。まだだ。", "거의 돌아올 준비가 됐어. 아직은 아냐.", "它们快要回来了。还没。", "它們快要回來了。還沒。", "Chúng sắp sẵn sàng quay lại. Chưa đâu.", "Mereka hampir siap kembali. Belum.", "พวกมันใกล้พร้อมจะกลับมาแล้ว ยัง", "Geri dönmeye neredeyse hazırlar. Henüz değil.", "Ya casi están listos para volver. Todavía no.", "Estão quase prontos pra voltar. Ainda não.", "Они почти готовы вернуться. Ещё нет.", "Вони майже готові повернутися. Ще ні."],
  "Nice day for it.": ["いい日だね。", "날 좋다.", "好天气。", "好天氣。", "Ngày đẹp trời.", "Hari yang cocok.", "วันนี้อากาศดี", "Tam günü.", "Buen día para ello.", "Belo dia pra isso.", "Хороший денёк.", "Гарний день."],
  "Long way from home.": ["家から遠くまで来たね。", "집에서 멀리 왔네.", "离家好远了。", "離家好遠了。", "Xa nhà quá.", "Jauh dari rumah.", "ไกลบ้านมาก", "Evden çok uzaktayız.", "Lejos de casa.", "Longe de casa.", "Далеко от дома.", "Далеко від дому."],
  "Look.": ["見て。", "봐.", "看。", "看。", "Nhìn kìa.", "Lihat.", "ดูสิ", "Bak.", "Mira.", "Olha.", "Смотри.", "Дивись."],
  "What now?": ["次は？", "이제 뭐 하지？", "接下来呢？", "接下來呢？", "Giờ sao?", "Sekarang apa?", "แล้วไงต่อ", "Şimdi ne?", "¿Y ahora qué?", "E agora?", "Что теперь?", "Що тепер?"],
  "Whoa.": ["おお。", "우와.", "哇哦。", "哇哦。", "Chà.", "Wah.", "ว้าว", "Vay.", "Hala.", "Uau.", "Ого.", "Ого."],
  "I don't like that.": ["それは嫌だな。", "저거 싫어.", "我不喜欢那个。", "我不喜歡那個。", "Ta không thích cái đó.", "Aku tak suka itu.", "ไม่ชอบเลย", "Bundan hoşlanmadım.", "No me gusta eso.", "Não gosto disso.", "Мне это не нравится.", "Мені це не подобається."],
  "Onwards.": ["先へ進もう。", "앞으로.", "继续前进。", "繼續前進。", "Tiến lên.", "Maju terus.", "ไปต่อ", "İleri.", "Adelante.", "Em frente.", "Вперёд.", "Вперед."],
};
